  const s = args[0];
  const result = [];
  let depth = 0;
  let start = -1;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (c === ' ') continue;
    if (c === '(') {
      if (depth === 0) start = i;
      depth++;
    } else if (c === ')') {
      depth--;
      if (depth === 0) {
        let group = '';
        for (let j = start; j <= i; j++) {
          if (s[j] !== ' ') group += s[j];
        }
        result.push(group);
      }
    }
  }
  return result;
}

