  const str = s.replace(/ /g, '');
  const result = [];
  let depth = 0;
  let start = 0;
  for (let i = 0; i < str.length; i++) {
    if (str[i] === '(') {
      if (depth === 0) start = i;
      depth++;
    } else if (str[i] === ')') {
      depth--;
      if (depth === 0) result.push(str.slice(start, i + 1));
    }
  }
  return result;
}

