  for (let i = 0; i < arr.length; i++) {
    let n = arr[i];
    let sum = 0;
    if (n < 0) {
      const s = String(-n);
      sum = -Number(s[0]);
      for (let j = 1; j < s.length; j++) {
        sum += Number(s[j]);
      }
    } else {
      const s = String(n);
      for (let j = 0; j < s.length; j++) {
        sum += Number(s[j]);
      }
    }
    if (sum > 0) count++;
  }
  return count;
}

